-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('beca06ae-f6d4-5d24-964c-dd14e451f22c'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Qu’est-ce que le fordisme ?', 'mcq', '["Une organisation à la chaîne avec standardisation et hauts salaires","Un système bancaire","Une politique fiscale","Un mouvement syndical"]'::jsonb, 0, 'Henry Ford paie mieux ses ouvriers pour qu’ils achètent ses voitures.', 1),
    ('bb00cc5c-8cf9-5ac9-b43f-4a4ee6590432'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Quel mécanisme soutient la consommation américaine des années 1920 ?', 'mcq', '["Le crédit à la consommation","La hausse des salaires agricoles","La baisse des impôts sur les ménages modestes","Les allocations publiques"]'::jsonb, 0, 'On achète à tempérament, ce qui gonfle l’endettement des ménages.', 2),
    ('cc0c267f-b5f0-5d63-844d-36b14c87f868'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Qu’est-ce que l’achat sur marge en Bourse ?', 'mcq', '["Acheter des actions en empruntant la majeure partie de la somme","Acheter des actions au comptant","Vendre à découvert","Acheter des obligations d’État"]'::jsonb, 0, 'Toute baisse oblige alors à vendre en catastrophe pour rembourser.', 3),
    ('2f63a340-ded8-53ce-a0e9-fe40d0b8c7b5'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Que permet le plan Dawes de 1924 ?', 'mcq', '["De financer les réparations allemandes par des prêts américains","D’annuler les dettes de guerre","De créer la Banque mondiale","De dévaluer le dollar"]'::jsonb, 0, 'Il met toute l’Europe sous dépendance des capitaux américains.', 4),
    ('4dffbce7-52e9-5676-8615-3d2d39293980'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Le secteur agricole américain profite pleinement de la prospérité des années 1920.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est en surproduction et en crise dès le début de la décennie.', 5),
    ('d2a832f1-5a41-59af-881d-beefafa37a1e'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Pourquoi la consommation ne suit-elle pas la production ?', 'mcq', '["Les salaires progressent moins vite que la productivité","La population diminue","Les prix augmentent trop vite","Les usines ferment"]'::jsonb, 0, 'Le décalage nourrit la surproduction.', 6),
    ('fbaa8888-ecc8-5931-813b-031c6456efd4'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Quel pays devient le principal créancier du monde après 1918 ?', 'mcq', '["Les États-Unis","Le Royaume-Uni","La France","L’Allemagne"]'::jsonb, 0, 'Ils prêtent à l’Europe pour financer sa reconstruction.', 7),
    ('6a2a9e20-5390-5375-ab58-7116119699d2'::uuid, '99a1a0e5-2e98-5b3f-9316-2950ca962382'::uuid, 'Quelle invention diffuse la publicité de masse dans les foyers américains ?', 'mcq', '["La radio","La télévision","Le téléphone","Le cinéma parlant seul"]'::jsonb, 0, 'Elle entre dans des millions de foyers au cours de la décennie.', 8),
    ('0ac2840c-d60b-5c42-a368-9b7dc9ad49cf'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Quelle date marque le début du krach de Wall Street ?', 'mcq', '["Le 24 octobre 1929","Le 3 septembre 1929","Le 11 novembre 1929","Le 1er janvier 1930"]'::jsonb, 0, 'Le « jeudi noir », suivi du mardi 29 octobre.', 1),
    ('0bb86cd6-7cb9-58a2-b1c9-94a02c75b456'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Pourquoi l’achat sur marge aggrave-t-il la chute ?', 'mcq', '["Les investisseurs doivent vendre pour rembourser leurs emprunts","Il fait monter les prix","Il bloque les échanges","Il protège les petits porteurs"]'::jsonb, 0, 'La baisse déclenche des ventes forcées, qui font encore baisser les cours.', 2),
    ('c45be4f7-c4f1-5ba0-aa61-66d34b7394c8'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Qu’est-ce qu’une panique bancaire ?', 'mcq', '["Une ruée des déposants pour retirer leur argent","Une fermeture décidée par l’État","Une fusion de banques","Une hausse des taux"]'::jsonb, 0, 'Aucune banque ne peut rembourser tous ses déposants en même temps.', 3),
    ('fd97c20c-91ba-5698-b598-bf29b7ac266f'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Quelle banque européenne fait faillite en 1931 ?', 'mcq', '["La Creditanstalt","La Deutsche Bank","La Barings","Le Crédit lyonnais"]'::jsonb, 0, 'Sa chute propage la crise à toute l’Europe centrale.', 4),
    ('eb52c424-9da3-5fd5-980b-53d41f532694'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Quelle est la réaction commerciale des États en 1930 ?', 'mcq', '["Le protectionnisme, avec le tarif Hawley-Smoot","La libéralisation des échanges","La création d’une monnaie commune","La suppression des douanes"]'::jsonb, 0, 'Le commerce mondial s’effondre de plus de moitié.', 5),
    ('6944896c-8f7e-5a4c-a3ca-aefa22d68791'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Quel pays européen est le plus violemment touché ?', 'mcq', '["L’Allemagne","Le Portugal","La Suède","L’Italie"]'::jsonb, 0, 'Elle dépendait entièrement des prêts américains : 6 millions de chômeurs en 1932.', 6),
    ('ff04b060-53fa-5924-8761-f64335c8e2d1'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'Que sont les Hoovervilles ?', 'mcq', '["Des bidonvilles de chômeurs américains","Des cités ouvrières modèles","Des camps de travail","Des quartiers résidentiels"]'::jsonb, 0, 'Le nom vise le président Hoover, jugé responsable.', 7),
    ('41d90c5d-5225-5c8c-883c-fb402b668119'::uuid, 'b9dfaddb-4e63-55b0-956b-60826d19c45c'::uuid, 'La crise de 1929 est restée limitée aux États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le retrait des capitaux américains la propage au monde entier.', 8),
    ('576d8776-f0bd-5f05-83c3-4e7a2d90d816'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Qui lance le New Deal aux États-Unis ?', 'mcq', '["Franklin D. Roosevelt","Herbert Hoover","Harry Truman","Woodrow Wilson"]'::jsonb, 0, 'Élu en 1932, il entre en fonction en mars 1933.', 1),
    ('b0a8b8ce-b1e7-5d0f-8126-57a24e9e9e31'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Quelle loi de 1935 crée une première protection sociale américaine ?', 'mcq', '["Le Social Security Act","Le Wagner Act","Le Glass-Steagall Act","Le National Recovery Act"]'::jsonb, 0, 'Retraites et assurance chômage naissent alors.', 2),
    ('494f5219-54eb-5881-adc3-4d1cc2afcd46'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Quel économiste théorise l’intervention de l’État pour relancer la demande ?', 'mcq', '["John Maynard Keynes","Adam Smith","Milton Friedman","Karl Marx"]'::jsonb, 0, 'Sa Théorie générale paraît en 1936.', 3),
    ('d199a2fd-37ce-5137-9f50-473ebf0d169a'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Quels acquis sociaux le Front populaire obtient-il en 1936 ?', 'mcq', '["Congés payés et semaine de 40 heures","La retraite à 60 ans","La Sécurité sociale","Le SMIC"]'::jsonb, 0, 'Les accords Matignon suivent des grèves avec occupation d’usines.', 4),
    ('3029043b-9dd6-5ee0-b6c6-2f763f8a92a9'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Comment l’Allemagne nazie résorbe-t-elle le chômage ?', 'mcq', '["Par les grands travaux et surtout le réarmement","Par la baisse des impôts","Par l’émigration","Par la réduction du temps de travail"]'::jsonb, 0, 'Le plan de quatre ans de 1936 prépare la guerre.', 5),
    ('0ce9598c-3bb1-5281-ae24-dfec2c87c917'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Le New Deal marque la fin du libéralisme classique aux États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’État devient un acteur permanent de la régulation économique.', 6),
    ('15bd5cd8-6997-5d1d-a9ac-74335718ddd3'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Qu’est-ce que l’autarcie ?', 'mcq', '["Une économie qui cherche à se suffire à elle-même","Une économie de marché ouverte","Un système de troc","Une union douanière"]'::jsonb, 0, 'Elle est recherchée par l’Allemagne et l’Italie des années 1930.', 7),
    ('20d4f03f-379e-5986-a6d5-4c4a377668b5'::uuid, '3453aae0-fe29-510f-996c-b1948bd0975c'::uuid, 'Quel grand aménagement symbolise les travaux publics du New Deal ?', 'mcq', '["La Tennessee Valley Authority","Le canal de Panama","Le barrage d’Assouan","L’Empire State Building"]'::jsonb, 0, 'Barrages, électrification et emplois dans une région pauvre.', 8),
    ('d513c641-3192-52a8-bc19-3652824ec989'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Quand Hitler devient-il chancelier ?', 'mcq', '["Le 30 janvier 1933","En novembre 1923","En août 1934","En septembre 1939"]'::jsonb, 0, 'Il est nommé légalement par le président Hindenburg.', 1),
    ('159b0710-dc5b-5aeb-a829-2ce1cc0e0fa2'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Quel événement sert de prétexte à la suspension des libertés en 1933 ?', 'mcq', '["L’incendie du Reichstag","La nuit de Cristal","Le putsch de Munich","La nuit des Longs Couteaux"]'::jsonb, 0, 'Le décret qui suit supprime les libertés fondamentales.', 2),
    ('7b8ffd2f-7df7-5511-91e6-676ac5500d2a'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Que prévoient les lois de Nuremberg de 1935 ?', 'mcq', '["L’exclusion des Juifs de la citoyenneté allemande","La création des camps","Le réarmement","L’annexion de l’Autriche"]'::jsonb, 0, 'Elles inscrivent le racisme dans le droit.', 3),
    ('5587001f-50f8-5ce5-9d78-29fd78b17fb2'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Qu’est-ce que le Lebensraum ?', 'mcq', '["L’espace vital que le régime veut conquérir à l’Est","Un programme de logement","Une organisation de jeunesse","Une police politique"]'::jsonb, 0, 'Il justifie l’expansion territoriale à venir.', 4),
    ('5bef8f03-e413-5337-94b2-ed2b46a59ab5'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Que se passe-t-il lors de la Nuit de Cristal en novembre 1938 ?', 'mcq', '["Un pogrom organisé contre les Juifs allemands","Un coup d’État manqué","L’élimination des chefs SA","L’annexion des Sudètes"]'::jsonb, 0, 'Synagogues incendiées, magasins pillés, arrestations massives.', 5),
    ('eeedf2a9-ecfb-55bf-93d1-8aa6b607bd9c'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Le premier camp de concentration nazi ouvre en 1933.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dachau ouvre dès mars 1933 pour les opposants politiques.', 6),
    ('8840baec-c1db-5897-a5c9-667bcf4e15fb'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Quel événement sportif sert de vitrine au régime en 1936 ?', 'mcq', '["Les Jeux olympiques de Berlin","La Coupe du monde de football","Le Tour d’Allemagne","Les Jeux d’hiver de Munich"]'::jsonb, 0, 'La propagande y met en scène une Allemagne pacifique et puissante.', 7),
    ('bd810ff0-bf36-5e0f-a37b-0c07e4479ab6'::uuid, '48c16b9c-a47b-5591-9c7e-ae73cde148bb'::uuid, 'Qui dirige la propagande du régime nazi ?', 'mcq', '["Joseph Goebbels","Heinrich Himmler","Hermann Göring","Rudolf Hess"]'::jsonb, 0, 'Il contrôle presse, radio, cinéma et culture.', 8),
    ('60360a09-edc9-5ad4-863d-40404b9c4825'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Quel épisode porte Mussolini au pouvoir en 1922 ?', 'mcq', '["La marche sur Rome","Le putsch de Munich","La révolution d’Octobre","Le coup d’État du 2 décembre"]'::jsonb, 0, 'Le roi le nomme chef du gouvernement plutôt que de résister.', 1),
    ('f9ab4946-5205-574a-8d86-26c7ca2ed9fa'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Comment appelle-t-on les milices fascistes ?', 'mcq', '["Les chemises noires","Les SA","Les Balilla","Les carabiniers"]'::jsonb, 0, 'Elles pratiquent la violence contre socialistes et syndicalistes.', 2),
    ('09b9fbcd-2c7c-5581-b638-03a531fd783e'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Quel assassinat marque un tournant en 1924 ?', 'mcq', '["Celui du député Matteotti","Celui du roi","Celui du pape","Celui de Gramsci"]'::jsonb, 0, 'Il ouvre la voie aux lois « fascistissimes » de 1925-1926.', 3),
    ('0a562b9d-9972-5693-8218-bfbbccd89c4c'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Que sont les accords du Latran de 1929 ?', 'mcq', '["Un accord entre l’État italien et le Vatican","Un traité avec l’Allemagne","Une alliance avec l’Espagne","Un accord commercial"]'::jsonb, 0, 'Ils règlent la question romaine et rallient une partie des catholiques.', 4),
    ('58af1afe-41b3-5e4d-8391-fed7139c7b62'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Quelle institution le fascisme n’a-t-il jamais supprimée ?', 'mcq', '["La monarchie","Le parlement","Les syndicats libres","La presse d’opposition"]'::jsonb, 0, 'Le roi destituera d’ailleurs Mussolini en juillet 1943.', 5),
    ('61b0ac23-18af-534c-ae55-06abd54b59fd'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Quel pays l’Italie fasciste conquiert-elle en 1935-1936 ?', 'mcq', '["L’Éthiopie","L’Albanie seule","La Libye","La Grèce"]'::jsonb, 0, 'La SDN sanctionne mollement : son impuissance est démontrée.', 6),
    ('e7c32271-77ae-5772-8ef4-1170bd809fec'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'L’Italie fasciste adopte des lois raciales en 1938.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elles imitent les lois de Nuremberg et marquent l’alignement sur Berlin.', 7),
    ('00fe476e-49a3-5e0e-9ebf-a74d662c9749'::uuid, '0e5a5fd8-4307-5fc9-bdef-e838a63e5e9e'::uuid, 'Comment appelle-t-on Mussolini dans le régime ?', 'mcq', '["Le Duce","Le Führer","Le Caudillo","Le Petit Père des peuples"]'::jsonb, 0, 'Le culte du chef est au cœur de la propagande fasciste.', 8),
    ('43624453-3482-5c79-b2fa-386cb8cc0bc6'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Quelle révolution porte les bolcheviks au pouvoir ?', 'mcq', '["Celle d’octobre 1917","Celle de février 1917","Celle de 1905","Celle de 1922"]'::jsonb, 0, 'Février renverse le tsar, octobre porte Lénine au pouvoir.', 1),
    ('a5af9ec0-7274-5431-89e1-491df5e5d82d'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qu’est-ce que la NEP ?', 'mcq', '["Un retour partiel au marché décidé en 1921","Un plan d’industrialisation","Une police politique","Une réforme agraire collectiviste"]'::jsonb, 0, 'Elle relance la production après le communisme de guerre.', 2),
    ('53bad90a-13a7-5169-b383-a47ba2f35c13'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qu’est-ce que la collectivisation des terres ?', 'mcq', '["Le regroupement forcé des paysans en fermes collectives","La distribution de terres aux paysans","La privatisation des terres","La mise en jachère des terres"]'::jsonb, 0, 'Kolkhozes et sovkhozes remplacent l’exploitation individuelle.', 3),
    ('3ef0b0ce-e35f-5d00-b757-7b5fd0d7bc21'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qui sont les koulaks ?', 'mcq', '["Les paysans considérés comme aisés, liquidés comme classe","Les ouvriers d’élite","Les cadres du parti","Les soldats de l’Armée rouge"]'::jsonb, 0, 'Leur « liquidation » accompagne la collectivisation.', 4),
    ('03d13187-278b-5cd3-afd6-d5eb6991040c'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qu’est-ce que le Holodomor ?', 'mcq', '["La grande famine d’Ukraine de 1932-1933","Une purge du parti","Un plan quinquennal","Un camp du Goulag"]'::jsonb, 0, 'Elle fait plusieurs millions de morts.', 5),
    ('9ce5ad54-7862-5dfd-8009-8b81a0e77528'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qu’est-ce que le Goulag ?', 'mcq', '["Le système des camps de travail soviétiques","La police secrète","Le parlement soviétique","Le plan économique"]'::jsonb, 0, 'Des millions de personnes y sont déportées.', 6),
    ('c546fb75-a570-5fbd-a58a-ac3bfcf7d23a'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Les grandes purges frappent aussi les cadres du parti et de l’armée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les procès de Moscou (1936-1938) décapitent l’appareil d’État.', 7),
    ('d3ef0811-b5ff-54b1-90f4-a3ebc8bf41ed'::uuid, '52537b26-debf-5028-80a4-0db18b8c1526'::uuid, 'Qu’est-ce que le réalisme socialiste ?', 'mcq', '["La doctrine artistique officielle du régime","Une théorie économique","Un courant philosophique libéral","Une méthode agricole"]'::jsonb, 0, 'L’art doit servir la construction du socialisme.', 8),
    ('88e40bd3-c77f-5f19-9a3b-3f89cb9e4c5c'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Quel trait est commun aux trois régimes totalitaires ?', 'mcq', '["Le parti unique fusionné avec l’État","L’idéologie raciale","La monarchie maintenue","L’économie de marché"]'::jsonb, 0, 'Avec le culte du chef, la propagande et la police politique.', 1),
    ('bfe61587-9b44-5dd3-a4b0-7aab875021a3'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Qu’est-ce qui distingue l’idéologie nazie de l’idéologie soviétique ?', 'mcq', '["Elle est raciale, quand l’autre est fondée sur la classe","Elle est religieuse","Elle est libérale","Elle est régionaliste"]'::jsonb, 0, 'Cette différence conduit à des politiques de destruction distinctes.', 2),
    ('14eabda7-20f3-5f11-b1e2-e4230da9a323'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Quelle philosophe popularise le concept de totalitarisme en 1951 ?', 'mcq', '["Hannah Arendt","Simone Weil","Raymond Aron seul","Karl Popper"]'::jsonb, 0, 'Les Origines du totalitarisme est publié cette année-là.', 3),
    ('280372d3-efad-50ed-8fe8-2e4f4fc00910'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Qu’est-ce que l’homme nouveau ?', 'mcq', '["L’individu que le régime prétend façonner par l’idéologie","Un slogan publicitaire","Un programme scolaire","Un type d’ouvrier qualifié"]'::jsonb, 0, 'Il justifie l’embrigadement dès l’enfance.', 4),
    ('8bb7165c-c5d7-5c43-beb8-4d9f2263b430'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Quel régime totalitaire conserve la monarchie et l’Église comme pouvoirs distincts ?', 'mcq', '["Le fascisme italien","Le nazisme","Le stalinisme","Aucun"]'::jsonb, 0, 'C’est l’une des raisons pour lesquelles il est jugé moins abouti.', 5),
    ('7e935ebf-f137-5fce-8991-95700a7d6d28'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Qu’est-ce que la politique d’apaisement ?', 'mcq', '["Les concessions des démocraties face aux exigences d’Hitler","Une politique sociale","Un plan de désarmement soviétique","Un accord commercial"]'::jsonb, 0, 'Les accords de Munich de 1938 en sont le symbole.', 6),
    ('d5b5e73b-4333-57c5-9ee0-9730d261d69f'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Un régime autoritaire et un régime totalitaire, c’est la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le second veut transformer l’individu, pas seulement le faire obéir.', 7),
    ('df55fd01-6b80-5ff8-be6c-f5a0070b54a9'::uuid, '251ed2ad-d6cd-5cdb-8f32-49f376adce24'::uuid, 'Pourquoi le concept de totalitarisme a-t-il été critiqué ?', 'mcq', '["Parce qu’il rapproche des régimes très différents et a servi d’arme politique","Parce qu’il est trop récent","Parce qu’il ne concerne que l’Italie","Parce qu’il est purement juridique"]'::jsonb, 0, 'Il reste un outil de comparaison, pas une identité.', 8),
    ('10ddcbc3-79f1-5078-9162-13861d20bb90'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'Quel pacte précède l’invasion de la Pologne ?', 'mcq', '["Le pacte germano-soviétique d’août 1939","Le pacte d’Acier","Les accords de Munich","Le pacte anti-Komintern"]'::jsonb, 0, 'Il partage secrètement l’Europe orientale entre Berlin et Moscou.', 1),
    ('bbbc5efe-b1cb-5bc3-a075-922d3a9b94b7'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'Qu’est-ce que la Blitzkrieg ?', 'mcq', '["Une guerre éclair combinant chars et aviation","Une guerre de tranchées","Un blocus naval","Un bombardement stratégique"]'::jsonb, 0, 'Elle explique l’effondrement rapide de la France en 1940.', 2),
    ('899ad7d8-47b9-5d9f-b752-549b500a7396'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'Quelle attaque fait entrer les États-Unis dans la guerre ?', 'mcq', '["Pearl Harbor, en décembre 1941","L’invasion de la Pologne","La bataille d’Angleterre","Le débarquement de Normandie"]'::jsonb, 0, 'Le Japon attaque la base américaine du Pacifique le 7 décembre 1941.', 3),
    ('da0412e3-3bf5-5aa5-ba8b-d47abc741697'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'Quelle bataille marque le tournant sur le front de l’Est ?', 'mcq', '["Stalingrad","Koursk seule","Moscou","Leningrad"]'::jsonb, 0, 'La VIe armée allemande capitule en février 1943.', 4),
    ('7b770943-2f85-5bd1-bcc1-b7b4ca8576c3'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'Quand a lieu le débarquement de Normandie ?', 'mcq', '["Le 6 juin 1944","Le 8 mai 1945","Le 2 septembre 1945","Le 11 novembre 1942"]'::jsonb, 0, 'Il ouvre le second front à l’Ouest réclamé par Staline.', 5),
    ('9cf83e9b-bf30-5c9d-8014-418b6a981d84'::uuid, 'a0df772b-1c80-5486-97cb-b9ba7c50b795'::uuid, 'La majorité des morts de la Seconde Guerre mondiale sont des civils.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Bombardements, famines, massacres et génocides en font une guerre contre les populations.', 6),
