    ('ed86bc7b-314d-5e00-978c-87ae67282dff'::uuid, '5e5c0a23-1705-5869-9ded-5a67f3b624d0'::uuid, 'Quelle rafle de juillet 1942 est exécutée par la police française ?', 'mcq', '["La rafle du Vél d’Hiv","La rafle de Marseille","La rafle du Marais","La rafle de Drancy"]'::jsonb, 0, 'Plus de 13 000 personnes arrêtées, dont plus de 4 000 enfants.', 7),
