    ('628c0d8b-b772-5b03-aae0-9f27582848b3'::uuid, '0c2c5765-faa0-5dec-b740-52699a8fc64b'::uuid, 'Quelle guerre de 1967 modifie durablement la carte de la région ?', 'mcq', '["La guerre des Six Jours","La guerre du Kippour","La guerre du Liban","La guerre du Golfe"]'::jsonb, 0, 'Israël occupe le Sinaï, Gaza, la Cisjordanie et le Golan.', 4),
    ('34038eb2-e1d1-5c96-b78f-d79cc3e28453'::uuid, '0c2c5765-faa0-5dec-b740-52699a8fc64b'::uuid, 'Quel événement déclenche le premier choc pétrolier ?', 'mcq', '["La guerre du Kippour de 1973","La révolution iranienne","La crise de Suez","La guerre Iran-Irak"]'::jsonb, 0, 'Les pays arabes de l’OPEP utilisent le pétrole comme arme.', 5),
    ('2d73be2d-ae90-5e34-a8a0-9ed2b34c93fe'::uuid, '0c2c5765-faa0-5dec-b740-52699a8fc64b'::uuid, 'Quels accords sont signés entre l’Égypte et Israël en 1978-1979 ?', 'mcq', '["Les accords de Camp David","Les accords d’Oslo","Les accords de Genève","Les accords de Madrid"]'::jsonb, 0, 'L’Égypte devient alors un allié des États-Unis.', 6),
    ('0c168da0-1429-53a8-bb6f-a69574ddec5a'::uuid, '0c2c5765-faa0-5dec-b740-52699a8fc64b'::uuid, 'La révolution iranienne de 1979 installe un régime allié des États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La République islamique est hostile aux deux superpuissances.', 7),
    ('02501da1-26e2-5064-9c7d-f64ff32c21dd'::uuid, '0c2c5765-faa0-5dec-b740-52699a8fc64b'::uuid, 'Quelle organisation donne aux pays producteurs un pouvoir sur les prix ?', 'mcq', '["L’OPEP","Le FMI","L’AIEA","La Ligue arabe"]'::jsonb, 0, 'Créée en 1960, elle s’impose lors du choc de 1973.', 8),
    ('449ffd37-322e-5229-bea3-1145255dfb5b'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Quand l’Inde et le Pakistan deviennent-ils indépendants ?', 'mcq', '["En 1947","En 1954","En 1960","En 1962"]'::jsonb, 0, 'La partition provoque des déplacements massifs et des centaines de milliers de morts.', 1),
    ('0dc0bf6d-101a-587e-9b96-57a8c5f65b51'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Quelle bataille précipite la fin de la guerre d’Indochine ?', 'mcq', '["Diên Biên Phu, en 1954","La bataille d’Alger","La bataille de Suez","La bataille de Bizerte"]'::jsonb, 0, 'Les accords de Genève suivent en juillet 1954.', 2),
    ('4707383b-40d4-5479-bd40-28500dd70d50'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Quels accords mettent fin à la guerre d’Algérie ?', 'mcq', '["Les accords d’Évian, en 1962","Les accords de Genève","Les accords de Camp David","Les accords de Bandung"]'::jsonb, 0, 'Huit ans de guerre s’achèvent après un référendum.', 3),
    ('68269462-34dc-5e67-b89e-09ce78bcd83d'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Quelle conférence de 1955 réunit des pays d’Asie et d’Afrique ?', 'mcq', '["La conférence de Bandung","La conférence de Belgrade","La conférence de Yalta","La conférence de San Francisco"]'::jsonb, 0, 'Elle condamne le colonialisme et affirme une voie propre.', 4),
    ('633cb2ec-0de1-50b3-8bc7-de1547d2b029'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Qu’est-ce que le mouvement des non-alignés ?', 'mcq', '["Un regroupement d’États refusant de choisir entre les deux blocs","Une alliance militaire du Sud","Une organisation économique","Un syndicat de producteurs de pétrole"]'::jsonb, 0, 'Fondé à Belgrade en 1961 autour de Nehru, Nasser et Tito.', 5),
    ('9142d6c5-b823-57d9-8df0-ccbcd9881cfc'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Quelle année est appelée « l’année de l’Afrique » ?', 'mcq', '["1960","1955","1947","1975"]'::jsonb, 0, 'Dix-sept États africains y accèdent à l’indépendance.', 6),
    ('7d21ca3b-7423-5b70-b7d4-c5cccae477e9'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Qui forge le terme « tiers-monde » ?', 'mcq', '["Alfred Sauvy, en 1952","Frantz Fanon","Jawaharlal Nehru","Léopold Sédar Senghor"]'::jsonb, 0, 'Par analogie avec le tiers état de 1789.', 7),
    ('57d61455-c1b5-5e03-b27f-cf4a12c9dfee'::uuid, 'c7db5938-1f9c-5117-9707-949e10b48aa1'::uuid, 'Les nouveaux États obtiennent en même temps souveraineté politique et indépendance économique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La dépendance aux matières premières et à l’aide extérieure persiste.', 8),
    ('7fcb5067-47fb-5686-a389-c1e6b0de2df2'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Quand la République populaire de Chine est-elle proclamée ?', 'mcq', '["Le 1er octobre 1949","En 1945","En 1958","En 1966"]'::jsonb, 0, 'Après la victoire des communistes sur les nationalistes de Tchang Kaï-chek.', 1),
    ('71ca8010-95df-554e-9681-5c70247047a5'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Qu’est-ce que le Grand Bond en avant ?', 'mcq', '["Un plan de collectivisation et d’industrialisation lancé en 1958","Une réforme scolaire","Une campagne militaire","Un plan de libéralisation économique"]'::jsonb, 0, 'Il provoque une famine de 20 à 40 millions de morts.', 2),
    ('8e58f69d-aedc-5293-9a9b-6a0818e88096'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Que sont les communes populaires ?', 'mcq', '["De vastes unités collectives regroupant terres, travail et vie quotidienne","Des conseils municipaux","Des coopératives volontaires","Des unités militaires"]'::jsonb, 0, 'Elles suppriment toute exploitation individuelle.', 3),
    ('2ddc5766-9982-5e73-9987-0acf63612209'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Qui Mao lance-t-il contre le parti pendant la Révolution culturelle ?', 'mcq', '["Les gardes rouges, issus de la jeunesse","L’Armée populaire seule","Les paysans","Les cadres du parti"]'::jsonb, 0, 'L’objectif est de reprendre le contrôle après l’échec du Grand Bond.', 4),
    ('549e82eb-64a5-5211-921b-9b9e7307e1ed'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Quand la Chine obtient-elle l’arme atomique ?', 'mcq', '["En 1964","En 1949","En 1972","En 1976"]'::jsonb, 0, 'Après la rupture avec l’URSS, elle assure seule sa dissuasion.', 5),
    ('4f5c71a3-8201-594f-9315-6dfdafd7c181'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'La Chine populaire entre à l’ONU en 1971.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle y prend le siège permanent au Conseil de sécurité, jusque-là occupé par Taïwan.', 6),
    ('08d046a7-308f-5c00-9da9-d86fa1a6ed92'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Quel président américain se rend à Pékin en 1972 ?', 'mcq', '["Richard Nixon","John Kennedy","Jimmy Carter","Lyndon Johnson"]'::jsonb, 0, 'Le rapprochement sino-américain bouscule la bipolarité.', 7),
    ('38b368d2-aa46-563c-9c77-3da0c8dedef7'::uuid, '8ec7173e-01b3-5e76-9e03-416ef38a5ffe'::uuid, 'Quelle rupture majeure intervient au début des années 1960 ?', 'mcq', '["La rupture entre la Chine et l’URSS","La rupture avec les États-Unis","La rupture avec l’Inde seule","La rupture avec le Vietnam"]'::jsonb, 0, 'Le camp communiste cesse d’être un bloc unique.', 8),
    ('5c64fb93-62b4-5458-aa05-66e65f588fd5'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Combien de grévistes compte le mouvement de mai 1968 en France ?', 'mcq', '["Près de 9 millions","Environ 1 million","Environ 3 millions","Environ 15 millions"]'::jsonb, 0, 'C’est la plus grande grève de l’histoire française.', 1),
    ('8af29269-0c26-5d25-8635-da9b2774c8bb'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Quel dirigeant tchécoslovaque incarne le Printemps de Prague ?', 'mcq', '["Alexander Dubcek","Vaclav Havel","Imre Nagy","Lech Walesa"]'::jsonb, 0, 'Il promeut « un socialisme à visage humain ».', 2),
    ('3930618b-957a-5d2a-a27f-708b9be38817'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Comment le Printemps de Prague se termine-t-il ?', 'mcq', '["Par l’intervention des chars du pacte de Varsovie en août 1968","Par des élections libres","Par un compromis avec Moscou","Par la chute du régime"]'::jsonb, 0, 'La doctrine Brejnev justifie l’intervention.', 3),
    ('a244e5a8-20c0-5a46-96c9-3ee5ed6f5808'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Qu’est-ce que la doctrine Brejnev ?', 'mcq', '["La souveraineté limitée des pays socialistes","La coexistence pacifique","La détente","L’endiguement"]'::jsonb, 0, 'Moscou s’autorise à intervenir chez ses satellites.', 4),
    ('3f6cebc1-8d20-5a39-baac-3466c7c5cb7f'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Quel dirigeant américain des droits civiques est assassiné en 1968 ?', 'mcq', '["Martin Luther King","Malcolm X","Rosa Parks","John Kennedy"]'::jsonb, 0, 'Son assassinat déclenche des émeutes dans de nombreuses villes.', 5),
    ('4db7a1ea-9beb-58df-822d-e412afb11ec4'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Quelle guerre nourrit la contestation étudiante américaine ?', 'mcq', '["La guerre du Vietnam","La guerre de Corée","La guerre du Golfe","La guerre d’Algérie"]'::jsonb, 0, 'La conscription et les images télévisées mobilisent les campus.', 6),
    ('48831c73-c3c3-5939-bb60-a17f55894abc'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Les contestations de 1968 touchent uniquement les pays occidentaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Prague, Varsovie et Mexico connaissent aussi leurs mouvements.', 7),
    ('9442ba0b-ed7b-5a00-be48-c765792bc480'::uuid, '57efbf03-bf1f-581f-b780-1c78e29fca34'::uuid, 'Quel facteur commun explique ces mobilisations ?', 'mcq', '["Une génération nombreuse, plus scolarisée, née dans la prospérité","La crise économique","La guerre nucléaire","La décolonisation achevée"]'::jsonb, 0, 'Le baby-boom arrive à l’âge adulte.', 8),
    ('4e3a4247-6bc1-5a4a-b77f-f90a54800b49'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quelle est la principale faiblesse institutionnelle de la IVe République ?', 'mcq', '["L’instabilité gouvernementale due à la prééminence de l’Assemblée","Un président trop puissant","L’absence de partis","Le suffrage censitaire"]'::jsonb, 0, '24 gouvernements se succèdent en douze ans.', 1),
    ('48c2c2f6-d09b-5143-802e-822ce8118328'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quelle protection sociale majeure est créée en 1945 ?', 'mcq', '["La Sécurité sociale","Les congés payés","Le SMIC","L’assurance chômage"]'::jsonb, 0, 'Elle applique le programme du Conseil national de la Résistance.', 2),
    ('b8a4875c-c803-5ab2-bd40-6a9928b20eff'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quelle communauté européenne naît en 1951 ?', 'mcq', '["La CECA","La CEE","L’UE","L’AELE"]'::jsonb, 0, 'Le charbon et l’acier, nerfs de la guerre, sont mis en commun.', 3),
    ('f56cb087-1e81-5d8c-a530-f5e3e550e290'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quel traité crée la CEE en 1957 ?', 'mcq', '["Le traité de Rome","Le traité de Paris","Le traité de Maastricht","Le traité de Bruxelles"]'::jsonb, 0, 'Six pays fondent un marché commun.', 4),
    ('a24ffd46-f844-5d16-854f-8b8f1f5f4cb8'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quelle défaite met fin à la guerre d’Indochine ?', 'mcq', '["Diên Biên Phu","Sedan","Suez","Alger"]'::jsonb, 0, 'Elle conduit aux accords de Genève de 1954.', 5),
    ('2177db71-29d5-5d91-8eaa-bea03f7dfdbd'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quel événement provoque la chute de la IVe République ?', 'mcq', '["La crise du 13 mai 1958 à Alger","La crise de Suez","Mai 68","Le référendum de 1962"]'::jsonb, 0, 'De Gaulle revient au pouvoir et fait adopter une nouvelle constitution.', 6),
    ('b00f2244-1d63-5161-b2b9-6fe71feb4606'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'La IVe République est le régime de la reconstruction et des Trente Glorieuses.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Croissance forte, plein-emploi et modernisation caractérisent la période.', 7),
    ('62ac2ad7-400a-5e17-8213-897c85036bce'::uuid, '65613d7c-2f6e-5f54-890e-06628369e362'::uuid, 'Quel pays devient le partenaire clé de la France dans la construction européenne ?', 'mcq', '["L’Allemagne de l’Ouest","Le Royaume-Uni","L’Espagne","La Suède"]'::jsonb, 0, 'La réconciliation franco-allemande est le moteur du projet.', 8),
    ('c84a3dbe-5dff-5a8d-ac54-b26dec400086'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quelle révision de 1962 modifie durablement la Ve République ?', 'mcq', '["L’élection du président au suffrage universel direct","Le quinquennat","La création du Conseil constitutionnel","La décentralisation"]'::jsonb, 0, 'Adoptée par référendum, elle donne au président une légitimité populaire directe.', 1),
    ('6f960bbc-31af-582e-b505-4977840e787c'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quels accords mettent fin à la guerre d’Algérie ?', 'mcq', '["Les accords d’Évian de mars 1962","Les accords de Genève","Les accords de Grenelle","Les accords de l’Élysée"]'::jsonb, 0, 'L’indépendance est ensuite approuvée par référendum.', 2),
    ('2d941e35-7935-5b28-b223-122c259dcf9a'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Qu’est-ce que l’OAS ?', 'mcq', '["Une organisation clandestine opposée à l’indépendance algérienne","Un parti gaulliste","Un mouvement syndical","Une agence de l’ONU"]'::jsonb, 0, 'Elle mène attentats et tentative de putsch.', 3),
    ('f4cf3f25-3b12-5095-8c1f-4aa358f2673e'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quelle décision militaire de 1966 marque l’indépendance française ?', 'mcq', '["Le retrait du commandement intégré de l’OTAN","L’entrée dans le pacte de Varsovie","La création de l’armée européenne","La fin du service militaire"]'::jsonb, 0, 'La France garde l’alliance mais refuse la subordination.', 4),
    ('aa83d829-c191-5a3d-a70b-4d3e57ee8da2'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quel traité de 1963 scelle la réconciliation franco-allemande ?', 'mcq', '["Le traité de l’Élysée","Le traité de Rome","Le traité de Paris","Le traité de Bruxelles"]'::jsonb, 0, 'Signé par de Gaulle et Adenauer.', 5),
    ('2be6343b-5cb7-5d06-9835-aeb3d15b7327'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'De Gaulle s’oppose à l’entrée du Royaume-Uni dans la CEE.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il y met son veto à deux reprises, en 1963 et 1967.', 6),
    ('2e17258e-02c4-5c3a-aa65-1675b0478175'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quand la France procède-t-elle à son premier essai nucléaire ?', 'mcq', '["En 1960","En 1958","En 1966","En 1968"]'::jsonb, 0, 'La force de frappe fonde la doctrine d’indépendance.', 7),
    ('889effa8-d757-5598-9676-6eddf11ef83e'::uuid, '3109def9-5d4f-5b22-afb3-84a4de5a65f5'::uuid, 'Quel événement conduit au départ de De Gaulle en 1969 ?', 'mcq', '["L’échec de son référendum d’avril 1969","Mai 68 directement","Une motion de censure","La défaite aux législatives"]'::jsonb, 0, 'Il quitte le pouvoir dès le lendemain du résultat.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('histoire-geo');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('histoire-geo')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 246 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 246 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
